// -----------------------------------------------------------------------------
// Database seed runner
// -----------------------------------------------------------------------------
// This file is executable with:
//   npx tsx prisma/article-seed-ALL-CATEGORIES-DETAILED-DB-SEED.ts
//
// It upserts by the Article.slug so it is safe to run repeatedly.
// Articles are explicitly published because the application commonly filters
// the article list by isPublished.
// -----------------------------------------------------------------------------

import "dotenv/config";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

async function main() {
  console.log(`Starting article seed: ${articleSeeds.length} articles...`);

  let created = 0;
  let updated = 0;
  let failed = 0;

  for (let i = 0; i < articleSeeds.length; i++) {
    const article = articleSeeds[i];

    try {
      const existing = await prisma.article.findUnique({
        where: { slug: article.slug },
        select: { id: true },
      });

      await prisma.article.upsert({
        where: { slug: article.slug },
        update: {
          title: article.title,
          excerpt: article.excerpt,
          content: article.content,
          author: article.author ?? "InterviewPrep team",
          seoTitle: article.seoTitle,
          seoDescription: article.seoDescription,
          isPublished: true,
          publishedAt: new Date(),
        },
        create: {
          title: article.title,
          slug: article.slug,
          excerpt: article.excerpt,
          content: article.content,
          author: article.author ?? "InterviewPrep team",
          seoTitle: article.seoTitle,
          seoDescription: article.seoDescription,
          isPublished: true,
          publishedAt: new Date(),
        },
      });

      if (existing) {
        updated++;
      } else {
        created++;
      }

      if ((i + 1) % 25 === 0 || i + 1 === articleSeeds.length) {
        console.log(
          `Progress: ${i + 1}/${articleSeeds.length} | created=${created} updated=${updated} failed=${failed}`
        );
      }
    } catch (error) {
      failed++;
      console.error(`Failed article ${i + 1}/${articleSeeds.length}: ${article.slug}`);
      console.error(error);
    }
  }

  const publishedCount = await prisma.article.count({
    where: { isPublished: true },
  });

  console.log("");
  console.log("Article seed completed.");
  console.log(`This seed file: ${articleSeeds.length}`);
  console.log(`Created: ${created}`);
  console.log(`Updated: ${updated}`);
  console.log(`Failed: ${failed}`);
  console.log(`Published articles currently in DB: ${publishedCount}`);

  if (failed > 0) {
    throw new Error(`${failed} article(s) failed to seed.`);
  }
}

main()
  .catch((error) => {
    console.error("Article seed failed:", error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
